<?php require __DIR__.'/../backend/config.php';$adm=!empty($_SESSION['admin']);$t=$_GET['t']??'';$id=(int)($_GET['id']??0);
if($t!==''){$w='r.token=?';$v=$t;}elseif($adm&&$id){$w='r.id=?';$v=$id;}else{http_response_code(404);exit('Not found');}
$s=$pdo->prepare("SELECT r.*,GROUP_CONCAT(COALESCE(c.name,CONCAT('Cottage ',c.cottage_no)) ORDER BY c.cottage_no SEPARATOR ', ') cn FROM reservations r LEFT JOIN reservation_cottages rc ON rc.reservation_id=r.id LEFT JOIN cottages c ON c.id=rc.cottage_id WHERE $w GROUP BY r.id");$s->execute([$v]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Not found');}
$title='Reservation #'.$r['id'].' – Sasa Beach Resort';include 'inc/header.php';$no='SBR-'.str_pad($r['id'],5,'0',STR_PAD_LEFT);$ps=$r['payment_status'];?>
<section><div class="wrap" style="max-width:680px"><h2>Reservation #<?=$r['id']?></h2><p class="noprint">Reservation status: <span class="pill <?=$r['status']?>"><?=$r['status']?></span></p>
<?php if($ps=='verified'):?><div class="receipt"><h3>Official Receipt · Sasa Beach Resort</h3><p>Purok Bangus, Lower Bayao, Tukuran, Zamboanga del Sur</p><table>
<tr><td>Receipt no.</td><td><?=$no?></td></tr><tr><td>Transaction reference</td><td><?=e($r['payment_ref']?:'Paid at resort')?></td></tr><tr><td>Payment date</td><td><?=date('F j, Y g:i A',strtotime($r['paid_at']))?></td></tr><tr><td>Payment method</td><td><?=$r['payment_method']=='ewallet'?'E-wallet':'Cash at resort'?></td></tr>
<tr><td>Guest</td><td><?=e($r['name'])?> (<?=e($r['contact_number'])?>)</td></tr><tr><td>Reservation date</td><td><?=date('F j, Y',strtotime($r['reservation_date']))?>, <?=$r['type']=='day'?'Day use':'Overnight'?>, arrival <?=substr($r['arrival_time'],0,5)?></td></tr><tr><td>Cottage(s)</td><td><?=e($r['cn'])?></td></tr><tr><td>Guests</td><td><?=$r['guests']?></td></tr>
<tr><td>Total</td><td>₱<?=number_format($r['total_amount'],2)?></td></tr><tr><td>Amount paid (50% down payment)</td><td><b>₱<?=number_format($r['down_payment'],2)?></b></td></tr><tr><td>Balance to pay at the resort</td><td>₱<?=number_format($r['total_amount']-$r['down_payment'],2)?></td></tr></table></div>
<div class="row noprint" style="margin-top:1rem"><button class="btn" onclick="print()">Print receipt</button><button class="btn alt" style="background:var(--sea)" onclick="print()">Download as PDF</button></div><p class="noprint"><small>To download, choose “Save as PDF” in the print window.</small></p>
<?php else:?><div class="note"><?php if($ps=='submitted')echo 'We received your e-wallet payment proof. The resort is verifying it. Refresh this page later. Your receipt will appear here once it is verified.';elseif($ps=='rejected')echo 'Your payment could not be verified. Please contact the resort.';else echo 'Pay the 50% down payment (₱'.number_format($r['down_payment']).') at the resort. Your receipt will appear here once the payment is confirmed.';?></div><?php endif;?>
</div></section><?php include 'inc/footer.php';
